        "emotional_tone": "热血，燃",
        "key_scenes": ["百姓投靠", "黑账交接", "整训队伍"]
      },
      {
        "chapter_number": 12,
        "chapter_title": "真假黄四郎",
        "core_event": "约翰设计抓了黄四郎的替身，让替身穿着黄四郎的衣服在鹅城游街，散播黄四郎被抓的消息，动摇黄四郎的势力根基。",
        "emotional_tone": "智斗，爽感",
        "key_scenes": ["抓替身", "游街散播消息", "黄四郎势力内部分化"]
      },
      {
        "chapter_number": 13,
        "chapter_title": "密室里的暗号",
        "core_event": "约翰收到来自碉楼密室的纸条，上面是亚瑟写的西部帮派专属暗号，约定在总攻那天里应外合。",
        "emotional_tone": "希望，铺垫高潮",
        "key_scenes": ["收到暗号", "确认亚瑟状态", "制定总攻计划"]
      },
      {
        "chapter_number": 14,
        "chapter_title": "散银子",
        "core_event": "约翰把黄四郎存在银行的银子全部散给鹅城百姓，百姓拿到银子后彻底倒向约翰，黄四郎成了孤家寡人。",
        "emotional_tone": "爽感，群像热血",
        "key_scenes": ["抢银行", "散银子", "全民支持总攻"]
      },
      {
        "chapter_number": 15,
        "chapter_title": "总攻前夜",
        "core_event": "总攻前约翰给兄弟们训话，用西部帮派的仪式给大家发子弹，回忆和亚瑟的过往，做好了最坏的打算。",
        "emotional_tone": "悲壮，燃",
        "key_scenes": ["战前训话", "发子弹仪式", "回忆亚瑟往事"]
      }
    ],
    "turning_point": "约翰确认亚瑟会在总攻时里应外合，鹅城百姓全部倒向自己，对抗黄四郎的最终条件成熟，总攻一触即发"
  },
  "act_three": {
    "description": "第三幕（25%篇幅，约3万字）：高潮对决，结局收尾。总攻黄四郎碉楼，救出亚瑟，约翰和黄四郎展开最终对决，所有伏笔回收，结局符合双IP的核心气质，不强行大团圆。",
    "key_chapters": [
      {
        "chapter_number": 16,
        "chapter_title": "碉楼攻坚战",
        "core_event": "总攻开始，约翰带着兄弟们用牛仔战术攻打碉楼，亚瑟在内部制造混乱打开城门，里应外合攻入碉楼内部。",
        "emotional_tone": "炸裂，暴力美学拉满",
        "key_scenes": ["总攻开始", "亚瑟内部接应", "攻入碉楼"]
      },
      {
        "chapter_number": 17,
        "chapter_title": "兄弟重逢",
        "core_event": "约翰在密室找到被囚禁的亚瑟，两个老兄弟时隔多年在民国鹅城重逢，对话充满荒野大镖客的经典梗。",
        "emotional_tone": "感动，情怀拉满",
        "key_scenes": ["密室重逢", "经典台词致敬", "兄弟联手"]
      },
      {
        "chapter_number": 18,
        "chapter_title": "天台对决",
        "core_event": "黄四郎逃到碉楼天台，约翰和亚瑟追上去，三个人展开西部式的拔枪对决，黄四郎被约翰用亚瑟当年送的最后一发子弹击毙。",
        "emotional_tone": "紧张，高潮炸裂",
        "key_scenes": ["天台对峙", "拔枪对决", "黄四郎被击毙"]
      },
      {
        "chapter_number": 19,
        "chapter_title": "鹅城的新秩序",
        "core_event": "黄四郎死了，鹅城恢复秩序，约翰把黄四郎的财产全部分给百姓，拒绝了百姓让他当鹅城王的请求，决定继续寻找剩下的范德林德帮成员。",
        "emotional_tone": "释然，温情",
        "key_scenes": ["分财产", "拒绝留任鹅城", "和汤师爷、百姓告别"]
      },
      {
        "chapter_number": 20,
        "chapter_title": "向西的马蹄声",
        "core_event": "约翰、亚瑟、六子带着愿意跟着走的麻匪兄弟，骑着马背着枪离开鹅城，向着西边出发，继续寻找失散的帮派成员，结局留下开放式悬念。",
        "emotional_tone": "潇洒，余韵悠长",
        "key_scenes": ["离开鹅城", "骑马向西", "开放式结局"]
      }
    ]
  }
}"}]}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
              "description": "期望的情感倾向"
            },
            "forbidden": {
              "type": "array",
              "description": "明确拒绝的元素",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "selected_recipe": {
      "type": "object",
      "description": "用户选定的创作配方（X-Y轴化学反应组合）",
      "required": [
        "x_axis_mode_id",
        "x_axis_mode_name",
        "y_axis_tags",
        "reaction_strength",
        "tension_stars",
        "forbidden_elements"
      ],
      "properties": {
        "x_axis_mode_id": {
          "type": "string",
          "pattern": "^[A-G]\\d{1,2}$",
          "enum": [
            "A1", "A2", "A3", "A4", "A5", "A6",
            "B7", "B8", "B9", "B10", "B11", "B12",
            "C13", "C14", "C15", "C16", "C17", "C18",
            "D19", "D20", "D21", "D22", "D23",
            "E24", "E25", "E26", "E27", "E28",
            "F29", "F30", "F31", "F32", "F33", "F34",
            "G35", "G36"
          ],
          "description": "普罗蒂36种剧情模式的标识符"
        },
        "x_axis_mode_name": {
          "type": "string",
          "description": "X轴模式的中文名称"
        },
        "y_axis_tags": {
          "type": "array",
          "description": "现代网文核心标签（表达载体）",
          "items": {
            "type": "string",
            "enum": [
              "双向暗恋",
              "系统流",
              "无限流",
              "种田流",
              "赛博朋克",
              "规则怪谈",
              "重生/穿越",
              "商战权谋",
              "克苏鲁",
              "第四天灾",
              "仙侠修真",
              "刑侦悬疑"
            ]
          },
          "minItems": 2,
          "maxItems": 3
        },
        "reaction_strength": {
          "type": "string",
          "enum": ["↗", "↘", "✷"],
          "description": "X轴与Y轴的化学反应强度符号"
        },
        "tension_stars": {
          "type": "integer",
          "minimum": 1,
          "maximum": 5,
          "description": "故事张力指数（1-5星）"
        },
        "forbidden_elements": {
          "type": "array",
          "description": "避雷红线（创作禁忌元素）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "x_axis_display": {
          "type": "string",
          "description": "X轴模式在故事中的具体显影方式"
        },
        "y_axis_combination_effect": {
          "type": "string",
          "description": "Y轴标签组合产生的效应描述"
        },
        "reaction_formula": {
          "type": "string",
          "description": "化学反应公式的一句话描述"
        },
        "platform_fit": {
          "type": "array",
          "description": "适合发布的平台类型",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "one_sentence_synopsis": {
      "type": "string",
      "description": "一句话故事梗概（30-50字）",
      "minLength": 30,
      "maxLength": 50
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "outline.schema.json",
  "title": "小说故事大纲",
  "description": "节奏规划参考，确保故事有合理的起承转合",
  "type": "object",
